import{_ as a,o as e,c as s,ae as r}from"./chunks/framework.Dh1jimFm.js";const m=JSON.parse('{"title":"AI Translation Overview","description":"","frontmatter":{},"headers":[],"relativePath":"ai-translation/overview.md","filePath":"ai-translation/overview.md"}'),n={name:"ai-translation/overview.md"};function i(l,t,o,d,c,h){return e(),s("div",null,t[0]||(t[0]=[r(`<h1 id="ai-translation-overview" tabindex="-1">AI Translation Overview <a class="header-anchor" href="#ai-translation-overview" aria-label="Permalink to &quot;AI Translation Overview&quot;">​</a></h1><p>Supervertaler integrates with leading AI language models for high-quality translation.</p><h2 id="supported-providers" tabindex="-1">Supported Providers <a class="header-anchor" href="#supported-providers" aria-label="Permalink to &quot;Supported Providers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Models</th><th>Speed</th><th>Quality</th><th>Cost</th></tr></thead><tbody><tr><td><strong>OpenAI</strong></td><td>GPT-4o, GPT-4-turbo</td><td>⚡ Fast</td><td>⭐⭐⭐⭐⭐</td><td>$$</td></tr><tr><td><strong>Anthropic</strong></td><td>Claude 3.5 Sonnet, Claude 3 Opus</td><td>⚡ Fast</td><td>⭐⭐⭐⭐⭐</td><td>$$</td></tr><tr><td><strong>Google</strong></td><td>Gemini 1.5 Pro</td><td>⚡ Fast</td><td>⭐⭐⭐⭐</td><td>$</td></tr><tr><td><strong>Ollama</strong></td><td>Llama 3, Mistral, etc.</td><td>🐢 Varies</td><td>⭐⭐⭐-⭐⭐⭐⭐</td><td>Free</td></tr></tbody></table><h2 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h2><ol><li><a href="./../get-started/api-keys.html">Set up API keys</a></li><li>Open a project with segments to translate</li><li>Select a segment</li><li>Press <code>Ctrl+T</code> to translate</li></ol><h2 id="translation-methods" tabindex="-1">Translation Methods <a class="header-anchor" href="#translation-methods" aria-label="Permalink to &quot;Translation Methods&quot;">​</a></h2><h3 id="single-segment" tabindex="-1">Single Segment <a class="header-anchor" href="#single-segment" aria-label="Permalink to &quot;Single Segment&quot;">​</a></h3><p>Translate one segment at a time:</p><ul><li>Select a segment</li><li>Press <code>Ctrl+T</code> or click <strong>Translate</strong> button</li><li>AI translation appears in the target cell</li><li>Review, edit, and confirm</li></ul><h3 id="batch-translation" tabindex="-1">Batch Translation <a class="header-anchor" href="#batch-translation" aria-label="Permalink to &quot;Batch Translation&quot;">​</a></h3><p>Translate multiple segments at once:</p><ul><li>Select segments (Shift+click for range)</li><li>Press <code>Ctrl+Shift+T</code> or use <strong>Edit → Batch Translate</strong></li><li>Configure options in the dialog</li><li>All selected segments are translated</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Supervertaler has multiple batch scopes (selected / not-started / etc.). Start with <strong>Edit → Batch Translate → Translate all not-started &amp; pre-translated</strong>.</p></div><h3 id="tm-ai-hybrid" tabindex="-1">TM + AI Hybrid <a class="header-anchor" href="#tm-ai-hybrid" aria-label="Permalink to &quot;TM + AI Hybrid&quot;">​</a></h3><p>Combine Translation Memory with AI:</p><ol><li>TM matches are checked first</li><li>High matches (e.g., &gt;90%) are used directly</li><li>Lower matches are AI-translated with TM context</li><li>No matches use pure AI translation</li></ol><h2 id="prompts" tabindex="-1">Prompts <a class="header-anchor" href="#prompts" aria-label="Permalink to &quot;Prompts&quot;">​</a></h2><p>Prompts control how the AI translates. A good prompt includes:</p><ul><li>Translation direction (source → target language)</li><li>Domain/subject matter</li><li>Style guidelines</li><li>Terminology rules</li><li>Special instructions</li></ul><h3 id="example-prompt" tabindex="-1">Example Prompt <a class="header-anchor" href="#example-prompt" aria-label="Permalink to &quot;Example Prompt&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>You are a professional Dutch-to-English translator specializing </span></span>
<span class="line"><span>in technical documentation. </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Maintain formal register. Use American English spelling. </span></span>
<span class="line"><span>Keep all formatting tags like {1}, &lt;b&gt;, &lt;/b&gt; in place.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Translate naturally while preserving the original meaning.</span></span></code></pre></div><p>See <a href="./prompts.html">Creating Prompts</a> and <a href="./prompt-library.html">Prompt Manager</a> for more.</p><h2 id="provider-selection" tabindex="-1">Provider Selection <a class="header-anchor" href="#provider-selection" aria-label="Permalink to &quot;Provider Selection&quot;">​</a></h2><h3 id="in-settings" tabindex="-1">In Settings <a class="header-anchor" href="#in-settings" aria-label="Permalink to &quot;In Settings&quot;">​</a></h3><ol><li>Go to <strong>Settings</strong> tab</li><li>Find <strong>LLM Settings</strong></li><li>Choose your preferred <strong>Provider</strong> and <strong>Model</strong></li><li>Save settings</li></ol><h3 id="per-translation" tabindex="-1">Per-Translation <a class="header-anchor" href="#per-translation" aria-label="Permalink to &quot;Per-Translation&quot;">​</a></h3><p>When batch translating, you can choose the provider in the dialog.</p><h2 id="quality-tips" tabindex="-1">Quality Tips <a class="header-anchor" href="#quality-tips" aria-label="Permalink to &quot;Quality Tips&quot;">​</a></h2><h3 id="get-better-results" tabindex="-1">Get Better Results <a class="header-anchor" href="#get-better-results" aria-label="Permalink to &quot;Get Better Results&quot;">​</a></h3><ol><li><strong>Use specific prompts</strong> - Include domain, style, and rules</li><li><strong>Provide context</strong> - Enable &quot;include context&quot; for surrounding segments</li><li><strong>Add glossary terms</strong> - Attach terminology for consistent translations</li><li><strong>Post-edit</strong> - AI is great but not perfect; always review</li></ol><h3 id="common-issues" tabindex="-1">Common Issues <a class="header-anchor" href="#common-issues" aria-label="Permalink to &quot;Common Issues&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Issue</th><th>Solution</th></tr></thead><tbody><tr><td>Wrong terminology</td><td>Add terms to glossary, include in prompt</td></tr><tr><td>Inconsistent style</td><td>Be more specific in your prompt</td></tr><tr><td>Tags removed/moved</td><td>Explicitly tell AI to preserve tags</td></tr><tr><td>Too literal</td><td>Ask for &quot;natural, fluent&quot; translation</td></tr></tbody></table><h2 id="cost-management" tabindex="-1">Cost Management <a class="header-anchor" href="#cost-management" aria-label="Permalink to &quot;Cost Management&quot;">​</a></h2><h3 id="api-costs" tabindex="-1">API costs <a class="header-anchor" href="#api-costs" aria-label="Permalink to &quot;API costs&quot;">​</a></h3><p>Cloud providers typically charge by usage (tokens). Pricing and free tiers change over time, so treat each provider dashboard as the source of truth.</p><h3 id="reducing-costs" tabindex="-1">Reducing Costs <a class="header-anchor" href="#reducing-costs" aria-label="Permalink to &quot;Reducing Costs&quot;">​</a></h3><ol><li><strong>Use Ollama</strong> (local) when appropriate</li><li><strong>Translate only what you need</strong> (for example not-started segments)</li><li><strong>Pre-translate with TM</strong> when you have good matches</li><li><strong>Use smaller/faster models</strong> for drafts, larger models for final passes</li></ol><hr><h2 id="learn-more" tabindex="-1">Learn More <a class="header-anchor" href="#learn-more" aria-label="Permalink to &quot;Learn More&quot;">​</a></h2><div class="sv-cards"><a class="sv-card" href="/ai-translation/single-segment"><span class="sv-card-title">Single Segment</span><span class="sv-card-desc">Translate one at a time →</span></a><a class="sv-card" href="/ai-translation/batch-translation"><span class="sv-card-title">Batch Translation</span><span class="sv-card-desc">Translate in bulk →</span></a><a class="sv-card" href="/ai-translation/prompts"><span class="sv-card-title">Creating Prompts</span><span class="sv-card-desc">Write effective prompts →</span></a><a class="sv-card" href="/ai-translation/ollama"><span class="sv-card-title">Local AI (Ollama)</span><span class="sv-card-desc">Free, private AI →</span></a></div>`,41)]))}const g=a(n,[["render",i]]);export{m as __pageData,g as default};
